/// <summary>
/// This class handles the dialog for modification of Excise Register Entry records
/// </summary>
class METExciseRegisterEntryModifyDialog
{
    protected Dialog        dialog;
    protected DialogField   dlgLodgement, dlgReceiptQty, dlgPermisionNumber, dlgTIUV, dlgReasonCode, dlgDeleteRecord;

    private METLodgement                metLodgement;
    private METReceiptQuantity          receiptQty;
    private METPermissionNumber         permissionNumber;
    private METTransportInsurance       tiuv;
    private InventCountingReasonCodeId  reasonCode;
    private NoYesId                     deleteRecord;
    
}

Method.Source:
    public static void main(Args _args)
    {
        METExciseRegisterEntryModifyDialog  dialogExciseRegisterEntry;
        METExciseRegisterEntry              metExciseRegisterEntry;

        //Check if the Args.Record() has the same TableID as the Table Buffer(custTable).
        if  (_args.record().TableId == tableNum(METExciseRegisterEntry))
        {
            //Assign the args records to table buffer and then pass it to salesLine_ds(FormDataSource)
            metExciseRegisterEntry      = _args.record();
 
            //Call Method which will be used to create the Dialog
            dialogExciseRegisterEntry = new METExciseRegisterEntryModifyDialog();
            dialogExciseRegisterEntry.updateExciseRegisterEntries(metExciseRegisterEntry);

            FormDataSource metExciseRegisterEntry_ds   = FormDataUtil::getFormDataSource(metExciseRegisterEntry);  //metExciseRegisterEntry.dataSource();
            metExciseRegisterEntry_ds.executeQuery();
        }
    }

    private void updateExciseRegisterEntries(METExciseRegisterEntry metExciseRegisterEntry)
    {
        dialog = this.dialog(metExciseRegisterEntry);

        //The code will only be executed if the user click on Yes
        if (dialog.run())
        {
            if(this.getFromDialog())
            {
                try
                {
                    ttsbegin;

                    //only modify if available Qty matches quantity i.e nothing has been consumed
                    METExciseRegisterEntryUpdateLog updateLog;
                    updateLog.Site                              = metExciseRegisterEntry.Site;
                    updateLog.ItemId                            = metExciseRegisterEntry.ItemId;
                    updateLog.OriginNumber                      = metExciseRegisterEntry.OriginNumber;
                    updateLog.METExciseRegisterEntryRefRecId    = metExciseRegisterEntry.RecId;
                    updateLog.ReasonCode                        = reasonCode;
                
                    metExciseRegisterEntry.selectForUpdate(true);

                    if(deleteRecord)
                    {
                        updateLog.ChangeType = VersioningChangeType::Deleted;
                        updateLog.LodgementOld = metExciseRegisterEntry.Lodgement;
                        updateLog.PermissionNumberOld = metExciseRegisterEntry.PermissionNumber;
                        updateLog.ReceiptQuantityOld = metExciseRegisterEntry.Quantity;
                        updateLog.TIUVOld = metExciseRegisterEntry.TIUV;

                        metExciseRegisterEntry.delete();
                    }
                    else
                    {
                        updateLog.ChangeType = VersioningChangeType::Updated;

                        if(metExciseRegisterEntry.Lodgement != metLodgement)
                        {
                            updateLog.LodgementOld = metExciseRegisterEntry.Lodgement;
                            updateLog.LodgementNew = metLodgement;

                            metExciseRegisterEntry.Lodgement = metLodgement;
                        }

                        if(metExciseRegisterEntry.PermissionNumber != permissionNumber)
                        {
                            updateLog.PermissionNumberOld = metExciseRegisterEntry.PermissionNumber;
                            updateLog.PermissionNumberNew = permissionNumber;

                            metExciseRegisterEntry.PermissionNumber = permissionNumber;
                        }

                        if(metExciseRegisterEntry.Quantity != receiptQty)
                        {
                            updateLog.ReceiptQuantityOld = metExciseRegisterEntry.Quantity;
                            updatelog.ReceiptQuantityNew = receiptQty;

                            metExciseRegisterEntry.ReceiptQuantity = receiptQty;
                            metExciseRegisterEntry.setAvailableQty();
                        }

                        if(metExciseRegisterEntry.TIUV != tiuv)
                        {
                            updateLog.TIUVOld = metExciseRegisterEntry.TIUV;
                            updateLog.TIUVNew = tiuv;

                            metExciseRegisterEntry.TIUV = tiuv;
                        }
                        metExciseRegisterEntry.update();
                    }

                    updateLog.insert();
                    ttscommit;
                    info(StrFmt('Changes have been updated for Origin Number - %1, ItemId - %2', metExciseRegisterEntry.OriginNumber,metExciseRegisterEntry.ItemId));
                }
                catch
                {
                    error('Unexpected error, Please try again or contact System Admin');
                }
                
            }
        }
    }

    /// <summary>
    /// Builds the dialog.
    /// </summary>
    /// <param name = "metExciseRegisterEntry">table record used to set initial values</param>
    /// <returns>The dialog</returns>
    protected Dialog dialog(metExciseRegisterEntry metExciseRegisterEntry)
    {
        //Create a Dialog with title
        dialog = new Dialog('Modify Excise Register Entries' );

        dlgDeleteRecord    = dialog.addField(ExtendedTypeStr(NoYesId),'Delete Record?');
        dlgDeleteRecord.value(strFmt('%1',NoYes::No));
        //Override modified method for dlgDeleteRecord
        dlgDeleteRecord.registerOverrideMethod(methodStr(FormStringControl, modified), methodStr(METExciseRegisterEntryModifyDialog, dialogDeleteRecord_modified), this);

        dlgLodgement        = dialog.addField(extendedTypeStr(METLodgement),'LodgementId');
        dlgLodgement.value(strFmt('%1',metExciseRegisterEntry.Lodgement));

        dlgPermisionNumber = dialog.addField(extendedTypeStr(METPermissionNumber),'Permission Number');
        dlgPermisionNumber.value(strFmt('%1',metExciseRegisterEntry.PermissionNumber));

        dlgReceiptQty   = dialog.addField(extendedTypeStr(Qty),'Quantity');
        dlgReceiptQty.value(strFmt('%1',metExciseRegisterEntry.ReceiptQuantity));

        dlgTIUV            = dialog.addField(extendedTypeStr(METTransportInsurance),'TIUV');
        dlgTIUV.value(strFmt('%1',metExciseRegisterEntry.TIUV));

        dlgReasonCode      = dialog.addField(extendedTypeStr(InventCountingReasonCodeId),'Reason Code');
        dlgReasonCode.fieldControl().mandatory(true);

        //Create a "Label" do Dialog
        dialog.addText('Do you wish to proceed?');

        dialog.formBuildDesign().dialogSize(0);

        return dialog;
    }

    /// <summary>
    /// disable controls on Dialog form if record need to be deleted
    /// </summary>
    /// <param name = "_dlgDeleteRecord">delete record dialog control</param>
    /// <returns>alwyas true</returns>
    private boolean dialogDeleteRecord_modified(FormCheckBoxControl _dlgDeleteRecord)
    {
        if (_dlgDeleteRecord.value() == true)
        {
            dlgLodgement.enabled(false);
            dlgPermisionNumber.enabled(false);
            dlgReceiptQty.enabled(false);
            dlgTIUV.enabled(false);
        }
        else
        {
            dlgLodgement.enabled(true);
            dlgPermisionNumber.enabled(true);
            dlgReceiptQty.enabled(true);
            dlgTIUV.enabled(true);
        }

        return true;
    }

    /// <summary>
    /// Retrieves values from the dialog after it is completed.
    /// </summary>
    /// <returns>true if values are retrieved successfully; otherwise, false.</returns>
    protected boolean getFromDialog()
    {
        boolean ret = true;

        deleteRecord        = dlgDeleteRecord.value();
        metLodgement        = dlgLodgement.value();
        receiptQty          = dlgReceiptQty.value();
        permissionNumber    = dlgPermisionNumber.value();
        tiuv                = dlgTIUV.value();
        reasonCode          = dlgReasonCode.value();

        //do any validation here
        if(deleteRecord == NoYes::No && metLodgement == '')
        {
            ret = checkFailed('Lodgement Number is mandatory');
        }

        return ret;
    }

public static METExciseRegisterEntryModifyDialog construct()
{
    return new METExciseRegisterEntryModifyDialog();
}
